import { useEffect, useState } from 'react';
import { getRules, saveRules } from '../api';
import { openInEditor } from '../openInEditor';
import type { Rule } from '../../server/alerts';

const SEVERITIES: Rule['severity'][] = ['info', 'warning', 'critical'];

export function AlertRules() {
  const [rules, setRules] = useState<Rule[]>([]);
  const [draft, setDraft] = useState<Rule[] | null>(null);
  const [error, setError] = useState('');
  useEffect(() => {
    getRules().then(setRules);
  }, []);

  const update = (i: number, patch: Partial<Rule>) =>
    setDraft((d) => d!.map((r, k) => (k === i ? { ...r, ...patch } : r)));

  const save = async () => {
    try {
      await saveRules(draft!);
      setRules(draft!);
      setDraft(null);
      setError('');
    } catch (e) {
      setError(e instanceof Error ? e.message : String(e));
    }
  };

  return (
    <section>
      <h2>
        Alert rules
        {!draft && <button onClick={() => setDraft(rules)}>Edit</button>}
        <button onClick={() => openInEditor('config/alerts.yaml')}>Edit YAML</button>
      </h2>
      <table>
        <thead>
          <tr><th>Rule</th><th>Condition</th><th>Severity</th></tr>
        </thead>
        <tbody>
          {(draft ?? rules).map((r, i) => (
            <tr key={r.id}>
              <td>
                {draft ? <input value={r.name} onChange={(e) => update(i, { name: e.target.value })} /> : r.name}{' '}
                {/* The id stays fixed: incidents store the id of the rule that opened them,
                    so a changed id would cut them off from their rule. */}
                <span className="chip">{r.id}</span>
              </td>
              <td>
                <code>{r.metric} {r.op}</code>{' '}
                {draft ? (
                  <input type="number" value={r.threshold}
                    onChange={(e) => update(i, { threshold: Number(e.target.value) })} />
                ) : (
                  <code>{r.threshold}</code>
                )}{' '}
                for {r.for}
              </td>
              <td>
                {draft ? (
                  <select value={r.severity} onChange={(e) => update(i, { severity: e.target.value as Rule['severity'] })}>
                    {SEVERITIES.map((s) => <option key={s}>{s}</option>)}
                  </select>
                ) : (
                  r.severity
                )}
              </td>
            </tr>
          ))}
        </tbody>
      </table>
      {draft && (
        <footer>
          {error && <p className="error">{error}</p>}
          <button onClick={save}>Save</button>
          <button onClick={() => { setDraft(null); setError(''); }}>Cancel</button>
        </footer>
      )}
    </section>
  );
}

import { mkdtemp, writeFile } from 'node:fs/promises';
import { tmpdir } from 'node:os';
import { join } from 'node:path';
import { loadRules, saveRules, validateRule, type Rule } from './alerts';

const RULE: Rule = { id: 'a', name: 'A', metric: 'm', op: '>', threshold: 1, for: '1m', severity: 'info' };

async function tempPath(): Promise<string> {
  return join(await mkdtemp(join(tmpdir(), 'rules-')), 'alerts.yaml');
}

test('loads rules from YAML', async () => {
  const path = await tempPath();
  await writeFile(path, 'rules:\n  - id: a\n    name: A\n    metric: m\n    op: ">"\n    threshold: 1\n    for: 1m\n    severity: info\n');
  expect((await loadRules(path))[0].id).toBe('a');
});

test('saves rules back to YAML', async () => {
  const path = await tempPath();
  await saveRules([RULE], path);
  expect(await loadRules(path)).toEqual([RULE]);
});

test('rejects a rule whose threshold is not a number', async () => {
  expect(validateRule({ ...RULE, threshold: NaN })).toBe('a: threshold must be a number');
  await expect(saveRules([{ ...RULE, threshold: NaN }], await tempPath())).rejects.toThrow('threshold');
});

